#!/usr/bin/env node
/**
 * reconstruct-historical-briefings.mjs — one-time historical correction
 *
 * Every archived daily briefing page (docs/briefing/<date>.html) since the
 * recency-window bug was introduced was generated by ranking the *entire*
 * feed.xml archive with no time filter, so each one shows the same handful
 * of permanently-10/10-scored editorial picks instead of that day's actual
 * news (see build-briefing.mjs's RECENCY_HOURS fix). This script
 * reconstructs what each dated archive *should* have shown, using:
 *
 *   - the real feed.xml content as it existed at the end of that day
 *     (fetched from GitHub's commit history — this repo commits feed.xml
 *     on every 6h update-feed run, so there is a snapshot per day),
 *   - the fixed 48h-recency ranking logic (imported from build-briefing.mjs,
 *     not reimplemented, so behavior can't drift from the live script),
 *   - corrected editorial-pick publish dates (from the current, already
 *     backfilled docs/feed.xml — see backfill-pick-dates.mjs) overlaid onto
 *     every historical snapshot, since the real-world publish date of an
 *     article doesn't depend on when we looked it up.
 *
 * It only rewrites the dated archive files (docs/briefing/<date>.html).
 * docs/briefing/index.html (the live "latest" page) is left untouched —
 * the live update-feed pipeline owns that file.
 *
 * Usage: node scripts/reconstruct-historical-briefings.mjs [--dry-run] [--only 2026-09-01,2026-09-02]
 */

import { readFileSync, writeFileSync, readdirSync } from 'fs';
import { execSync } from 'child_process';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';
import { parseFeed, dedupKey } from './feed-update.mjs';
import { renderBriefingBody, pageShell } from './build-briefing.mjs';

const __dir = dirname(fileURLToPath(import.meta.url));
const ROOT = resolve(__dir, '..');
const BRIEFING_DIR = resolve(ROOT, 'docs/briefing');
const SETTINGS = resolve(ROOT, 'docs/data/settings.json');
const FEED = resolve(ROOT, 'docs/feed.xml');

const DRY_RUN = process.argv.includes('--dry-run');
const onlyFlag = process.argv.indexOf('--only');
const ONLY = onlyFlag >= 0 ? new Set(process.argv[onlyFlag + 1].split(',')) : null;

const REPO = 'fromknowware/bifurcation-memory-index';
const TOKEN = execSync('gh auth token').toString().trim();

async function ghApi(path) {
  const res = await fetch(`https://api.github.com${path}`, {
    headers: { Authorization: `Bearer ${TOKEN}`, Accept: 'application/vnd.github+json' },
  });
  if (!res.ok) throw new Error(`GitHub API ${path} -> ${res.status} ${res.statusText}`);
  return res.json();
}

async function fetchRawAtCommit(path, sha) {
  const res = await fetch(`https://raw.githubusercontent.com/${REPO}/${sha}/${path}`, {
    headers: { Authorization: `Bearer ${TOKEN}` },
  });
  if (!res.ok) throw new Error(`raw ${path}@${sha.slice(0, 8)} -> ${res.status} ${res.statusText}`);
  return res.text();
}

/** Last commit touching docs/feed.xml for each calendar date (UTC) covering [since, until). */
async function lastFeedCommitPerDate(since, until) {
  const byDate = new Map();
  for (let page = 1; ; page++) {
    const commits = await ghApi(
      `/repos/${REPO}/commits?path=docs/feed.xml&since=${since}&until=${until}&per_page=100&page=${page}`,
    );
    for (const c of commits) {
      const date = c.commit.committer.date.slice(0, 10);
      const existing = byDate.get(date);
      if (!existing || c.commit.committer.date > existing.date) {
        byDate.set(date, { sha: c.sha, date: c.commit.committer.date });
      }
    }
    if (commits.length < 100) break;
  }
  return byDate;
}

function buildCorrectedPickDates() {
  const current = parseFeed(readFileSync(FEED, 'utf8'));
  const map = new Map();
  for (const it of current) {
    if (it.editorialPick) map.set(dedupKey(it), it.publishedAt);
  }
  return map;
}

async function main() {
  const settings = JSON.parse(readFileSync(SETTINGS, 'utf8'));
  const correctedPickDates = buildCorrectedPickDates();
  console.log(`reconstruct: ${correctedPickDates.size} corrected editorial-pick dates loaded`);

  const allDates = readdirSync(BRIEFING_DIR)
    .filter((f) => /^\d{4}-\d{2}-\d{2}\.html$/.test(f))
    .map((f) => f.replace('.html', ''))
    .sort();
  const targetDates = ONLY ? allDates.filter((d) => ONLY.has(d)) : allDates;
  console.log(`reconstruct: ${targetDates.length} target dates (${targetDates[0]}..${targetDates[targetDates.length - 1]})`);

  const since = new Date(new Date(targetDates[0] + 'T00:00:00Z').getTime() - 24 * 3600 * 1000).toISOString();
  const until = new Date(new Date(targetDates[targetDates.length - 1] + 'T00:00:00Z').getTime() + 24 * 3600 * 1000).toISOString();
  const commitByDate = await lastFeedCommitPerDate(since, until);

  let written = 0;
  let skipped = 0;

  for (const date of targetDates) {
    const commit = commitByDate.get(date);
    if (!commit) {
      console.warn(`  SKIP ${date}: no feed.xml commit found for this date`);
      skipped++;
      continue;
    }

    const xml = await fetchRawAtCommit('docs/feed.xml', commit.sha);
    const items = parseFeed(xml);
    let corrections = 0;
    for (const it of items) {
      if (it.editorialPick) {
        const real = correctedPickDates.get(dedupKey(it));
        if (real && real !== it.publishedAt) {
          it.publishedAt = real;
          corrections++;
        }
      }
    }

    const now = new Date(commit.date);
    // Archives that existed as of this date, oldest reconstructable first —
    // mirrors what the live script's directory listing would have shown at
    // that point in time (it only ever looks backward from "now").
    const previous = allDates
      .filter((d) => d <= date)
      .sort()
      .reverse()
      .slice(0, 14)
      .map((d) => `${d}.html`);

    const { body, top, pool } = renderBriefingBody({ items, now, settings, previous, manualEditorial: undefined });
    const html = pageShell(`Daily Briefing — ${date}`, body);

    console.log(`  ${date} (feed@${commit.sha.slice(0, 8)}, ${commit.date}): pool=${pool.length} picks-corrected=${corrections} top=${top.length}`);

    if (!DRY_RUN) {
      writeFileSync(resolve(BRIEFING_DIR, `${date}.html`), html);
    }
    written++;
  }

  console.log(`reconstruct: ${written} written, ${skipped} skipped${DRY_RUN ? ' [dry-run, nothing written]' : ''}`);
}

main().catch((e) => {
  console.error(e);
  process.exit(1);
});
